package nl.juiced.guhs.feature.vadsrijk.wereld;

import java.io.BufferedReader;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

import javax.annotation.Nullable;

import net.minecraft.core.BlockPos;
import net.minecraft.core.Direction;

/**
 * 1.10.3: the central return portals of the safe towns ("every safe zone at least one central portal"), GENERATED by
 * tools/vadsrijk/stadsleven/terugportalen.py into data/guhs/vadsrijk/terugportalen.txt (the same pass stamps them into the map
 * tiles; the live world gets them via /guhs vadsrijk patch portaal_&lt;stad&gt;). Zone 1's older ones (kamp jetty, Zwamzoet west,
 * De Haven) stay in {@link WereldPlekken} as terugportaal_*.
 */
public final class TerugportaalPlekken {
    /** One portal: the town, the frame centre column (u 0 at stand level), the frame's axis, the POI id and its stand spot. */
    public record Portaal(String stad, BlockPos frame, Direction.Axis as, String poiId, BlockPos poi) {
    }

    public static final List<Portaal> PORTALEN;
    /** POI id -> stand spot in front of the portal (like WereldPlekken.ALLE's terugportaal_*). */
    public static final Map<String, BlockPos> ALLE;

    static {
        List<Portaal> l = new ArrayList<>();
        try (InputStream in = TerugportaalPlekken.class.getResourceAsStream("/data/guhs/vadsrijk/terugportalen.txt")) {
            if (in != null) {
                BufferedReader r = new BufferedReader(new InputStreamReader(in, StandardCharsets.UTF_8));
                for (String regel; (regel = r.readLine()) != null; ) {
                    String[] d = regel.trim().split("\s+");
                    if (d.length >= 10 && d[0].equals("terugportaal")) {
                        int x = Integer.parseInt(d[2]), y = Integer.parseInt(d[3]), z = Integer.parseInt(d[4]);
                        Direction.Axis as = d[5].equals("z") ? Direction.Axis.Z : Direction.Axis.X;
                        l.add(new Portaal(d[1], new BlockPos(x, y, z), as, d[6],
                                new BlockPos(Integer.parseInt(d[7]), Integer.parseInt(d[8]), Integer.parseInt(d[9]))));
                    }
                }
            }
        } catch (Exception e) {
            com.mojang.logging.LogUtils.getLogger().warn("[Vadsrijk] terugportalen.txt niet leesbaar: {}", e.toString());
        }
        PORTALEN = List.copyOf(l);
        Map<String, BlockPos> m = new LinkedHashMap<>();
        PORTALEN.forEach(p -> m.put(p.poiId(), p.poi()));
        ALLE = Collections.unmodifiableMap(m);
    }

    private TerugportaalPlekken() {
    }

    @Nullable
    public static BlockPos plek(String id) {
        return ALLE.get(id);
    }

    /** The portal blocks of a portal (6 wide along its axis, 6 high): u -3..2, v 0..5. */
    public static List<BlockPos> portaalCellen(Portaal p) {
        List<BlockPos> uit = new ArrayList<>();
        for (int u = -3; u <= 2; u++) {
            for (int v = 0; v <= 5; v++) {
                uit.add(p.as() == Direction.Axis.X ? p.frame().offset(u, v, 0) : p.frame().offset(0, v, u));
            }
        }
        return uit;
    }
}
